using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;
public partial class ActorNaturalMaterialEditorOperations:RefCounted
{
    private readonly NaturalMaterialEngineOperations _engine=new();private readonly ImageTextureMaterialRendererOperations _render=new();private readonly ImageMaterialBrowserOperations _browser=new();private readonly Expression _equal=Equality();private static Expression Equality(){var expression=new Expression();expression.Parse("a == b",new[]{"a","b"});return expression;}
    private static T Ui<T>(Control owner,string name) where T:GodotObject=>owner.Get(name).AsGodotObject() as T??throw new InvalidOperationException(name);private static Settings Current(Control owner)=>owner.Get("_settings").AsGodotDictionary();
    public void setup(Control owner,string context)
    {
        owner.Name="NaturalMaterialEditor";owner.AddThemeConstantOverride("separation",6);var swatch=Ui<ColorRect>(owner,"_swatch");swatch.Name="NaturalMaterialPreview";swatch.CustomMinimumSize=new Vector2(160,90);swatch.MouseFilter=Control.MouseFilterEnum.Ignore;owner.AddChild(swatch);var title=Ui<Label>(owner,"_title");title.AutowrapMode=TextServer.AutowrapMode.WordSmart;owner.AddChild(title);var browse=new Button{Name="natural_material_browse",Text="Browse & edit material…",TooltipText="Uses the same materials and saved presets as Brush and Bucket. Changes appear immediately on this surface."};browse.Pressed+=()=>open_browser(owner);owner.AddChild(browse);owner.AddChild(new Label{Name="NaturalMaterialOwnership",Text=context=="linked"?"Linked resource • edits update this file. Use Make Unique in the material slot for a local copy.":context=="saved"?"Saved resource • edits update actors that use this file.":"Local instance • save shared presets in the browser",AutowrapMode=TextServer.AutowrapMode.WordSmart,Modulate=new Color("819db4")});var advanced=new VBoxContainer{Visible=false};var toggle=new CheckButton{Text="3D surface settings"};toggle.Toggled+=value=>advanced.Visible=value;owner.AddChild(toggle);owner.AddChild(advanced);var mapping=Ui<OptionButton>(owner,"_mapping");mapping.Name="natural_material_mapping";mapping.AddItem("UV mapping");mapping.AddItem("Triplanar mapping");advanced.AddChild(mapping);mapping.ItemSelected+=index=>change(owner,"mapping",index==1?"triplanar":"uv");var relief=Ui<SpinBox>(owner,"_relief");number(advanced,"Relief strength",relief,0,2,.01);relief.Name="natural_material_relief";relief.ValueChanged+=value=>change(owner,"relief",value);var automatic=Ui<CheckButton>(owner,"_automatic_metallic");automatic.Text="Use material's metallic response";var metallic=Ui<SpinBox>(owner,"_metallic");automatic.Toggled+=value=>change(owner,"metallic",value?-1:metallic.Value);advanced.AddChild(automatic);number(advanced,"Metallic response",metallic,0,1,.01);metallic.Name="natural_material_metallic";metallic.ValueChanged+=value=>change(owner,"metallic",value);var timer=Ui<Timer>(owner,"_commit_timer");timer.OneShot=true;timer.WaitTime=.3;timer.Timeout+=()=>finish_edit(owner);owner.AddChild(timer);sync_from_source(owner);
    }
    public void number(VBoxContainer parent,string title,SpinBox input,double minimum,double maximum,double step){parent.AddChild(new Label{Text=title});input.MinValue=minimum;input.MaxValue=maximum;input.Step=step;input.SizeFlagsHorizontal=Control.SizeFlags.ExpandFill;parent.AddChild(input);}
    public void sync_from_source(Control owner){if(!owner.Call("_reader_valid").AsBool())return;var settings=_engine.normalize(owner.Call("_read_native").AsGodotDictionary());if(_equal.Execute(new GArray{settings,Current(owner)}).AsBool())return;if(owner.Get("_pending").AsBool()){Ui<Timer>(owner,"_commit_timer").Stop();owner.Set("_pending",false);}owner.Set("_settings",settings);update_controls(owner);var browser=owner.Get("_browser").As<Control>();if(GodotObject.IsInstanceValid(browser)&&!browser!.Call("is_closed").AsBool())browser.Call("set_material_value",_engine.material_from_settings(settings));}
    public void update_controls(Control owner){owner.Set("_syncing",true);var settings=Current(owner);using var material=_engine.material_from_settings(settings);Ui<ColorRect>(owner,"_swatch").Material=_render.material(material,new Vector2(160,90),Transform2D.Identity,false);Ui<Label>(owner,"_title").Text=settings.GetValueOrDefault("label",material.Get("material_id")).ToString();Ui<OptionButton>(owner,"_mapping").Select(settings.GetValueOrDefault("mapping","uv").AsString()=="triplanar"?1:0);Ui<SpinBox>(owner,"_relief").SetValueNoSignal(settings.GetValueOrDefault("relief",0.0).AsDouble());double metallic=settings.GetValueOrDefault("metallic",-1.0).AsDouble();Ui<CheckButton>(owner,"_automatic_metallic").SetPressedNoSignal(metallic<0);var input=Ui<SpinBox>(owner,"_metallic");input.Editable=metallic>=0;input.SetValueNoSignal(Math.Max(0,metallic));owner.Set("_syncing",false);}
    public void change(Control owner,string key,Variant value){if(owner.Get("_syncing").AsBool())return;var updated=Current(owner).Duplicate(true);updated[key]=value;edit(owner,updated);}
    public void edit(Control owner,Settings settings){if(!owner.Call("_writer_valid").AsBool())return;if(!owner.Get("_pending").AsBool()){owner.Set("_original",owner.Call("_read_native").AsGodotDictionary().Duplicate(true));owner.Set("_pending",true);}owner.Set("_settings",_engine.normalize(settings));owner.Call("_write_native",Current(owner).Duplicate(true),"preview",owner.Get("_original"));update_controls(owner);Ui<Timer>(owner,"_commit_timer").Start();}
    public void finish_edit(Control owner){if(!owner.Get("_pending").AsBool())return;owner.Set("_pending",false);if(owner.Call("_writer_valid").AsBool())owner.Call("_write_native",Current(owner).Duplicate(true),"commit",owner.Get("_original"));}
    public void input(Control owner,InputEvent input){if(owner.Get("_pending").AsBool()&&input is InputEventKey key&&key.Pressed&&!key.Echo&&(key.CtrlPressed||key.MetaPressed)&&key.Keycode is Key.Z or Key.Y)finish_edit(owner);}
    public void open_browser(Control owner){finish_edit(owner);var existing=owner.Get("_browser").As<Control>();if(GodotObject.IsInstanceValid(existing)&&!existing!.IsQueuedForDeletion()&&!existing.Call("is_closed").AsBool()){existing.Show();return;}Node host=owner;var ancestor=owner.GetParent();while(ancestor!=null&&ancestor is not Window){if(ancestor is Control){host=ancestor;if(ancestor.Name=="SceneWorkspace")break;}ancestor=ancestor.GetParent();}var browser=_browser.open_for_material(host,_engine.material_from_settings(Current(owner)),Callable.From<Resource>(value=>edit(owner,_engine.settings_from_material(value))));owner.Set("_browser",browser);browser.Connect("edit_committed",new Callable(owner,"_finish_edit"));}
    public void exit_tree(Control owner){finish_edit(owner);var browser=owner.Get("_browser").As<Control>();if(GodotObject.IsInstanceValid(browser)&&!browser!.IsQueuedForDeletion())browser.Call("close");}
}
